public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be requested.');
            }

            Schema.DescribeSObjectResult objectDescribe =
                describeObject(objectApiName);

            if (!objectDescribe.isAccessible()) {
                throw new SearchException('You cannot read the requested object.');
            }

            // Normalize explicitly rather than relying on schema-map key casing.
            Map<String, Schema.SObjectField> fieldsByLowerName =
                new Map<String, Schema.SObjectField>();
            Map<String, Schema.SObjectField> objectFields =
                objectDescribe.fields.getMap();

            for (String fieldName : objectFields.keySet()) {
                fieldsByLowerName.put(
                    fieldName.toLowerCase(),
                    objectFields.get(fieldName)
                );
            }

            Schema.DescribeFieldResult idDescribe =
                readableField('Id', fieldsByLowerName);

            List<String> selectFields =
                new List<String>{ idDescribe.getName() };
            Set<String> selectedNames =
                new Set<String>{ idDescribe.getName().toLowerCase() };

            for (String requestedName : fields) {
                Schema.DescribeFieldResult fieldDescribe =
                    readableField(requestedName, fieldsByLowerName);
                String canonicalName = fieldDescribe.getName();

                // Id is always selected; avoid duplicate SELECT expressions.
                if (selectedNames.add(canonicalName.toLowerCase())) {
                    selectFields.add(canonicalName);
                }
            }

            Map<String, Object> binds = new Map<String, Object>{
                'rowLimit' => maxRows
            };
            List<String> conditions = new List<String>();
            Integer filterIndex = 0;

            if (filters != null) {
                for (String filterName : filters.keySet()) {
                    Schema.DescribeFieldResult fieldDescribe =
                        readableField(filterName, fieldsByLowerName);

                    if (!fieldDescribe.isFilterable()) {
                        throw new SearchException(
                            'Field cannot be filtered: ' + fieldDescribe.getName()
                        );
                    }

                    String bindName = 'filterValue' + String.valueOf(filterIndex);
                    filterIndex++;

                    // Bind every value, including null; never concatenate UI values.
                    binds.put(bindName, filters.get(filterName));
                    conditions.add(fieldDescribe.getName() + ' = :' + bindName);
                }
            }

            String canonicalOrderBy;
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult fieldDescribe =
                    readableField(orderByField, fieldsByLowerName);

                if (!fieldDescribe.isSortable()) {
                    throw new SearchException(
                        'Field cannot be sorted: ' + fieldDescribe.getName()
                    );
                }
                canonicalOrderBy = fieldDescribe.getName();
            }

            // Only canonical, describe-validated identifiers enter the query text.
            String soql =
                'SELECT ' + String.join(selectFields, ', ') +
                ' FROM ' + objectDescribe.getName();

            if (!conditions.isEmpty()) {
                soql += ' WHERE ' + String.join(conditions, ' AND ');
            }
            if (canonicalOrderBy != null) {
                soql += ' ORDER BY ' + canonicalOrderBy + ' ASC';
            }
            soql += ' LIMIT :rowLimit';

            // USER_MODE enforces CRUD, FLS, sharing, and applicable restriction rules.
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            // Also normalize query failures, such as incompatible UI value types.
            throw new SearchException(
                'The search could not be completed. Check object and field ' +
                'access, query support, and filter value compatibility.'
            );
        }
    }

    private static Schema.DescribeSObjectResult describeObject(String apiName) {
        if (String.isBlank(apiName)) {
            throw new SearchException('The requested object does not exist.');
        }

        Map<String, Schema.SObjectType> objectsByName =
            Schema.getGlobalDescribe();

        for (String knownName : objectsByName.keySet()) {
            if (knownName.equalsIgnoreCase(apiName)) {
                return objectsByName.get(knownName).getDescribe();
            }
        }

        throw new SearchException('The requested object does not exist.');
    }

    private static Schema.DescribeFieldResult readableField(
        String apiName,
        Map<String, Schema.SObjectField> fieldsByLowerName
    ) {
        if (String.isBlank(apiName)) {
            throw new SearchException('Field names must not be blank.');
        }

        Schema.SObjectField fieldToken =
            fieldsByLowerName.get(apiName.toLowerCase());

        if (fieldToken == null) {
            throw new SearchException(
                'The requested field does not exist on the object: ' + apiName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        if (!fieldDescribe.isAccessible()) {
            throw new SearchException(
                'You cannot read the requested field: ' + fieldDescribe.getName()
            );
        }

        return fieldDescribe;
    }
}
