public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        @InvocableVariable
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>();
        Set<String> emailsToFind = new Set<String>();

        for (Request request : requests) {
            String email = request == null ? null : normalizeEmail(request.email);
            normalizedEmails.add(email);
            if (email != null) {
                emailsToFind.add(email);
            }
        }

        Map<String, Id> contactIdsByEmail = new Map<String, Id>();

        if (!emailsToFind.isEmpty()) {
            // Email matching is case-insensitive. Id breaks CreatedDate ties.
            // User mode enforces CRUD/FLS as well as record-level access.
            for (Contact contactRecord : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToFind
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String email = normalizeEmail(contactRecord.Email);
                if (!contactIdsByEmail.containsKey(email)) {
                    contactIdsByEmail.put(email, contactRecord.Id);
                }
            }
        }

        for (String email : normalizedEmails) {
            Result result = new Result();
            result.contactId = email == null ? null : contactIdsByEmail.get(email);
            result.found = result.contactId != null;
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
