public with sharing class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static OrderPayloadParser.Order parse(String body) {
        try {
            if (String.isBlank(body)) {
                throw new PayloadException('The request body must not be blank.');
            }

            Map<String, Object> payload = requireObject(
                JSON.deserializeUntyped(body),
                'The request body'
            );

            Order result = new Order();
            result.lines = new List<Line>();
            result.total = 0;

            result.orderNumber = optionalString(payload.get('number'), 'number');
            if (String.isBlank(result.orderNumber)) {
                throw new PayloadException('number is required and must not be blank.');
            }

            result.orderDate = parseDate(payload.get('date'));
            result.currencyCode = optionalString(payload.get('currency'), 'currency');

            if (payload.get('customer') != null) {
                Map<String, Object> customer = requireObject(
                    payload.get('customer'),
                    'customer'
                );
                result.customerEmail = optionalString(
                    customer.get('email'),
                    'customer.email'
                );
            }

            Object rawLines = payload.get('lines');
            if (rawLines != null) {
                if (!(rawLines instanceof List<Object>)) {
                    throw new PayloadException('lines must be a JSON array.');
                }

                List<Object> entries = (List<Object>) rawLines;
                for (Integer i = 0; i < entries.size(); i++) {
                    Line parsedLine = parseLine(entries[i], i);
                    result.lines.add(parsedLine);
                    result.total += parsedLine.lineTotal;
                }
            }

            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            // Normalize malformed JSON, invalid dates and numeric conversion failures.
            throw new PayloadException('Invalid order payload: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null || order.total == null) {
            throw new PayloadException('An order with a total is required.');
        }

        Map<String, Object> acknowledgement = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => (order.lines == null ? 0 : order.lines.size()),
            'total' => order.total
        };
        return JSON.serialize(acknowledgement);
    }

    private static Line parseLine(Object rawLine, Integer index) {
        String path = 'lines[' + index + ']';
        Map<String, Object> entry = requireObject(rawLine, path);

        Line result = new Line();
        result.sku = optionalString(entry.get('sku'), path + '.sku');
        if (String.isBlank(result.sku)) {
            throw new PayloadException(path + '.sku is required and must not be blank.');
        }

        Decimal quantity = requireNumber(entry.get('quantity'), path + '.quantity');
        if (
            quantity <= 0 ||
            quantity > 2147483647 ||
            quantity != quantity.setScale(0, System.RoundingMode.DOWN)
        ) {
            throw new PayloadException(
                path + '.quantity must be a positive Integer.'
            );
        }
        result.quantity = quantity.intValue();

        result.unitPrice = requireNumber(entry.get('unitPrice'), path + '.unitPrice');
        if (result.unitPrice < 0) {
            throw new PayloadException(path + '.unitPrice must not be negative.');
        }

        result.discount = 0;
        if (entry.get('discount') != null) {
            result.discount = requireNumber(entry.get('discount'), path + '.discount');
        }
        if (result.discount < 0 || result.discount > 1) {
            throw new PayloadException(path + '.discount must be between 0 and 1.');
        }

        Decimal unroundedTotal =
            result.quantity * result.unitPrice * (1 - result.discount);
        result.lineTotal = unroundedTotal.setScale(2, System.RoundingMode.HALF_UP);

        return result;
    }

    private static Map<String, Object> requireObject(Object value, String path) {
        if (value == null || !(value instanceof Map<String, Object>)) {
            throw new PayloadException(path + ' must be a JSON object.');
        }
        return (Map<String, Object>) value;
    }

    private static String optionalString(Object value, String path) {
        if (value == null) {
            return null;
        }
        if (!(value instanceof String)) {
            throw new PayloadException(path + ' must be a JSON string.');
        }
        return (String) value;
    }

    private static Decimal requireNumber(Object value, String path) {
        if (
            value == null ||
            !(
                value instanceof Integer ||
                value instanceof Long ||
                value instanceof Decimal ||
                value instanceof Double
            )
        ) {
            throw new PayloadException(path + ' is required and must be a JSON number.');
        }

        return Decimal.valueOf(String.valueOf(value));
    }

    private static Date parseDate(Object value) {
        String dateText = optionalString(value, 'date');
        if (dateText == null) {
            return null;
        }
        if (!Pattern.matches('[0-9]{4}-[0-9]{2}-[0-9]{2}', dateText)) {
            throw new PayloadException('date must use the ISO yyyy-MM-dd format.');
        }

        return Date.newInstance(
            Integer.valueOf(dateText.substring(0, 4)),
            Integer.valueOf(dateText.substring(5, 7)),
            Integer.valueOf(dateText.substring(8, 10))
        );
    }
}
