public with sharing class AccountScoringJob implements Queueable {
    private static final Integer CHUNK_SIZE = 200;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = new List<Id>();
        if (accountIds != null) {
            this.accountIds.addAll(accountIds);
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        // Explicitly configure the root's stack depth. This overrides the
        // Developer Edition default and enables chained execution in tests.
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth =
            ((accountIds.size() - 1) / CHUNK_SIZE) + 1;

        return System.enqueueJob(new AccountScoringJob(accountIds), options);
    }

    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        Integer chunkSize = Math.min(CHUNK_SIZE, accountIds.size());
        List<Id> currentIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < chunkSize) {
                currentIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentIds
            WITH USER_MODE
        ];

        for (Account account : accounts) {
            if (account.AnnualRevenue != null &&
                account.AnnualRevenue >= 1000000) {
                account.Rating = 'Hot';
            } else if (account.AnnualRevenue != null &&
                       account.AnnualRevenue >= 100000) {
                account.Rating = 'Warm';
            } else {
                account.Rating = 'Cold';
            }
        }

        update as user accounts;

        if (!remainingIds.isEmpty()) {
            if (context == null) {
                // A direct execute(null) invocation has no queued root.
                // Configure the remaining work as a new chain.
                start(remainingIds);
            } else {
                // Children inherit the root's configured maximum stack depth.
                System.enqueueJob(new AccountScoringJob(remainingIds));
            }
        }
    }
}
