public without sharing class OpportunityPipelineHandler {
    // These are org-wide derived totals. System-mode access intentionally
    // includes all opportunities, regardless of the initiating user's access.
    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> newRecords,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        switch on operation {
            when AFTER_INSERT, AFTER_UNDELETE {
                for (Opportunity current : newRecords) {
                    addAccountId(accountIds, current.AccountId);
                }
            }
            when AFTER_UPDATE {
                for (Opportunity current : newRecords) {
                    Opportunity previous = oldMap.get(current.Id);

                    // The legacy Account trigger changes only the reporting
                    // rating. Such updates cannot affect these totals.
                    if (
                        current.AccountId != previous.AccountId ||
                        current.Amount != previous.Amount ||
                        current.IsClosed != previous.IsClosed
                    ) {
                        addAccountId(accountIds, previous.AccountId);
                        addAccountId(accountIds, current.AccountId);
                    }
                }
            }
            when AFTER_DELETE {
                for (Opportunity previous : oldMap.values()) {
                    addAccountId(accountIds, previous.AccountId);
                }
            }
            when else {
                return;
            }
        }

        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    private static void addAccountId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        // Lock parents before reading the children so concurrent recalculations
        // for the same accounts are serialized.
        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ]);

        if (accountsById.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = accountsById.keySet();
        Map<Id, AggregateResult> totalsByAccountId =
            new Map<Id, AggregateResult>();

        for (AggregateResult result : [
            SELECT AccountId,
                   SUM(Amount) pipelineTotal,
                   COUNT(Id) opportunityCount
            FROM Opportunity
            WHERE AccountId IN :existingAccountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            totalsByAccountId.put((Id) result.get('AccountId'), result);
        }

        List<Account> updates = new List<Account>();

        for (Account existing : accountsById.values()) {
            Decimal pipelineTotal = 0;
            Integer opportunityCount = 0;
            AggregateResult result = totalsByAccountId.get(existing.Id);

            if (result != null) {
                Decimal summedAmount = (Decimal) result.get('pipelineTotal');
                pipelineTotal = summedAmount == null ? 0 : summedAmount;
                opportunityCount = (Integer) result.get('opportunityCount');
            }

            // Accounts absent from the aggregate results retain the explicit
            // zero defaults, including when their last open opportunity leaves.
            if (
                existing.FB_Open_Pipeline__c != pipelineTotal ||
                existing.FB_Open_Opportunities__c != opportunityCount
            ) {
                updates.add(new Account(
                    Id = existing.Id,
                    FB_Open_Pipeline__c = pipelineTotal,
                    FB_Open_Opportunities__c = opportunityCount
                ));
            }
        }

        // No transaction-wide "already processed" flag or ID set: later DML
        // statements must recalculate again. Relevant-field filtering above
        // stops the legacy rating-only recursion.
        if (!updates.isEmpty()) {
            // Propagate failures so opportunity changes cannot commit with
            // stale account totals.
            update updates;
        }
    }
}
