/**
 * Purges expired integration logs in bounded batch transactions.
 * Runs in system context without sharing so retention applies org-wide.
 */
public without sharing class LogPurgeJob
    implements Schedulable, Database.Batchable<SObject> {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Database.executeBatch(new LogPurgeJob(), 200);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime referenceTime = System.now();
        Datetime standardCutoff = referenceTime.addDays(-30);
        Datetime errorCutoff = referenceTime.addDays(-180);

        // Explicitly include blank levels. Strict comparisons retain records
        // created exactly at either applicable cutoff.
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :errorCutoff
               OR (
                   CreatedDate < :standardCutoff
                   AND (Level__c = null OR Level__c != 'ERROR')
               )
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<SObject> scope
    ) {
        // Let deletion failures surface as failed batch transactions rather
        // than silently ignoring them. Other batch transactions can continue.
        delete scope;
    }

    public void finish(Database.BatchableContext context) {
        // No post-processing required.
    }

    /**
     * Schedules daily execution at 02:00 in the scheduling user's time zone.
     */
    public static Id scheduleNightly() {
        return (Id) System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
