public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> totalsByAccount = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return totalsByAccount;
        }

        for (Id accountId : accountIds) {
            totalsByAccount.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
                AND IsWon = true
                AND CloseDate = THIS_YEAR
            WITH USER_MODE
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            totalsByAccount.put(accountId, totalAmount == null ? 0 : totalAmount);
        }

        return totalsByAccount;
    }
}
