    // Answers run inside the mocked methods, allowing temporal assertions and
    // snapshots without depending on mutable arguments retained by ApexMocks.
    private class RecordingAnswer implements fflib_Answer {
        private Fixture fixture;
        private String operation;

        RecordingAnswer(Fixture fixture, String operation) {
            this.fixture = fixture;
            this.operation = operation;
        }

        public Object answer(fflib_InvocationOnMock invocation) {
            if (operation == 'authenticate') {
                fixture.events.add('authenticate');
                if (fixture.authenticationError != null) {
                    throw new BillingException(fixture.authenticationError);
                }
                fixture.authenticated = true;
            } else if (operation == 'invoice') {
                System.assertEquals(
                    true,
                    fixture.authenticated,
                    'Authentication must complete before every invoice'
                );
                Id accountId = (Id) invocation.getArgument(0);
                fixture.events.add('invoice:' + accountId);

                if (fixture.invoiceErrors.containsKey(accountId)) {
                    throw new BillingException(fixture.invoiceErrors.get(accountId));
                }
                System.assertEquals(
                    true,
                    fixture.invoiceNumbers.containsKey(accountId),
                    'Unexpected account invoiced: ' + accountId
                );
                return fixture.invoiceNumbers.get(accountId);
            } else if (operation == 'dirty') {
                Opportunity opp = (Opportunity) invocation.getArgument(0);
                fixture.events.add('dirty:' + opp.Id);
                fixture.dirtySnapshots.put(
                    opp.Id,
                    opp.clone(true, false, false, false)
                );
            } else if (operation == 'commit') {
                fixture.events.add('commit');
            }
            return null;
        }
    }

