@IsTest
private class OpportunitiesServiceTest {
    /*
     * Factory observability limitation:
     *
     * Application.Domain.setMock registers a domain by SObjectType, not by the
     * records passed to Domain.newInstance. Consequently, these tests verify
     * selection, domain invocation, arguments, and commit ordering, but cannot
     * distinguish wrapping the selected records from wrapping a different
     * Opportunity list. Likewise, merely obtaining an unused mock from a
     * static factory is not observable.
     *
     * Enforcing those portions of the contract against every possible mutation
     * requires an injectable factory seam in the production code. Stubbing
     * domain.getRecords() would not establish that construction used those
     * records.
     */

    // Unlike a type matcher, this deliberately matches null arguments too.
    private class AnyArgument implements fflib_IMatcher {
        public Boolean matches(Object argument) {
            return true;
        }
    }

    private static Decimal anyPercentage() {
        return (Decimal) fflib_Match.matches(new AnyArgument());
    }

    private static fflib_ISObjectUnitOfWork anyUnitOfWork() {
        return (fflib_ISObjectUnitOfWork)
            fflib_Match.matches(new AnyArgument());
    }

    private static Set<Id> anyIds() {
        return (Set<Id>) fflib_Match.matches(new AnyArgument());
    }

    private class RecordInvocation implements fflib_Answer {
        private List<String> events;
        private String eventName;

        RecordInvocation(List<String> events, String eventName) {
            this.events = events;
            this.eventName = eventName;
        }

        public Object answer(fflib_InvocationOnMock invocation) {
            events.add(eventName);
            return null;
        }
    }

    private class Fixture {
        fflib_ApexMocks mocks;
        IOpportunitiesSelector selector;
        IOpportunities domain;
        fflib_ISObjectUnitOfWork uow;

        Set<Id> ids;
        List<Opportunity> selected;
        List<String> events;

        Integer initialQueries;
        Integer initialDmlStatements;

        Fixture() {
            initialQueries = Limits.getQueries();
            initialDmlStatements = Limits.getDmlStatements();

            mocks = new fflib_ApexMocks();
            selector = (IOpportunitiesSelector)
                mocks.mock(IOpportunitiesSelector.class);
            domain = (IOpportunities) mocks.mock(IOpportunities.class);
            uow = (fflib_ISObjectUnitOfWork)
                mocks.mock(fflib_ISObjectUnitOfWork.class);

            Id firstId = fflib_IDGenerator.generate(Opportunity.SObjectType);
            Id secondId = fflib_IDGenerator.generate(Opportunity.SObjectType);

            ids = new Set<Id>{ firstId, secondId };
            selected = new List<Opportunity>{
                new Opportunity(
                    Id = firstId,
                    Name = 'First opportunity',
                    Amount = 123.45
                ),
                new Opportunity(
                    Id = secondId,
                    Name = 'Second opportunity',
                    Amount = 987.65
                )
            };
            events = new List<String>();

            mocks.startStubbing();

            // These type stubs must exist before registering factory mocks.
            mocks.when(selector.sObjectType())
                .thenReturn(Opportunity.SObjectType);
            mocks.when(domain.sObjectType())
                .thenReturn(Opportunity.SObjectType);
            mocks.when(selector.selectById(ids)).thenReturn(selected);

            ((IOpportunities) mocks.doAnswer(
                new RecordInvocation(events, 'applyDiscount'),
                domain
            )).applyDiscount(anyPercentage(), anyUnitOfWork());

            ((fflib_ISObjectUnitOfWork) mocks.doAnswer(
                new RecordInvocation(events, 'commitWork'),
                uow
            )).commitWork();

            mocks.stopStubbing();

            Application.Domain.setMock(domain);
            Application.Selector.setMock(selector);
            Application.UnitOfWork.setMock(uow);
        }

        void assertNoDatabaseWork() {
            System.assertEquals(
                initialQueries,
                Limits.getQueries(),
                'The service test must not execute SOQL.'
            );
            System.assertEquals(
                initialDmlStatements,
                Limits.getDmlStatements(),
                'The service test must not execute DML.'
            );
        }

        void assertNothingAppliedOrCommitted() {
            ((IOpportunitiesSelector) mocks.verify(selector, 0))
                .selectById(anyIds());

            ((IOpportunities) mocks.verify(domain, 0))
                .applyDiscount(anyPercentage(), anyUnitOfWork());

            ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0))
                .commitWork();

            System.assertEquals(
                0,
                events.size(),
                'Neither applyDiscount nor commitWork may run.'
            );
            assertNoDatabaseWork();
        }

        void assertAppliedAndCommitted(Decimal percentage) {
            // Check both the precise request and the total selection count.
            ((IOpportunitiesSelector) mocks.verify(selector, 1))
                .selectById(ids);
            ((IOpportunitiesSelector) mocks.verify(selector, 1))
                .selectById(anyIds());

            // The percentage must be unchanged and the injected UoW forwarded.
            ((IOpportunities) mocks.verify(domain, 1))
                .applyDiscount(percentage, uow);

            // Also reject additional calls with different or null arguments.
            ((IOpportunities) mocks.verify(domain, 1))
                .applyDiscount(anyPercentage(), anyUnitOfWork());

            ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1))
                .commitWork();

            // Answers record execution order, not verification order.
            System.assertEquals(
                new List<String>{ 'applyDiscount', 'commitWork' },
                events,
                'Apply exactly once, then commit exactly once.'
            );
            assertNoDatabaseWork();
        }
    }

