        List<Boolean> originalOptOuts = new List<Boolean>{
            true, false, true, true, true, false, true, false
        };
        List<Boolean> expectedOptOuts = new List<Boolean>{
            false, false, false, false, true, false, true, false
        };

        Map<Id, SObject> existingRecords = new Map<Id, SObject>();
        List<Contact> records = new List<Contact>();

        for (Integer i = 0; i < oldEmails.size(); i++) {
            Contact oldRecord = new Contact(
