                LastName = 'Email case ' + i,
                Email = oldEmails[i],
                HasOptedOutOfEmail = originalOptOuts[i]
            );
            existingRecords.put(oldRecord.Id, oldRecord);

            Contact newRecord = oldRecord.clone(true, false, false, false);
            newRecord.Email = newEmails[i];
            records.add(newRecord);
        }

        fflib_SObjectDomain.Test.Database.onUpdate(records, existingRecords);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        for (Integer i = 0; i < records.size(); i++) {
            System.assertEquals(
