public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork unitOfWork =
            Application.UnitOfWork.newInstance(
                new fflib_SObjectUnitOfWork.UserModeDML(AccessLevel.USER_MODE)
            );

        Date closeDate = Date.today();
        Integer closedCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName == 'Closed Won') {
                continue;
            }

            unitOfWork.registerDirty(new Opportunity(
                Id = opportunity.Id,
                StageName = 'Closed Won',
                CloseDate = closeDate
            ));

            // Publish only after the unit of work's DML succeeds.
            // This is not an after-transaction-commit guarantee: with
            // Publish Immediately, a later caller rollback cannot retract
            // an event. That stronger guarantee requires Publish After Commit.
            unitOfWork.registerPublishAfterSuccess(new Deal_Won__e(
                Opportunity_Id__c = String.valueOf(opportunity.Id),
                Amount__c = opportunity.Amount
            ));

            closedCount++;
        }

        if (closedCount > 0) {
            unitOfWork.commitWork();
        }

        return closedCount;
    }
}
