public with sharing class ContactEmailMatcher {
    public class Request {
        @InvocableVariable(required=true)
        public String email;

        public Request() {}
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        public Result() {}
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> orderedEmails = new List<String>();
        Set<String> emailsToMatch = new Set<String>();

        for (Request request : requests) {
            String email = normalizeEmail(request == null ? null : request.email);
            orderedEmails.add(email);

            if (email != null) {
                emailsToMatch.add(email);
            }
        }

        Map<String, Id> contactIdsByEmail = new Map<String, Id>();

        if (!emailsToMatch.isEmpty()) {
            // Standard Email fields are whitespace-trimmed when persisted.
            // Email comparisons in SOQL are case-insensitive.
            // User mode additionally enforces object and field permissions.
            for (Contact candidate : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailsToMatch
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String email = normalizeEmail(candidate.Email);

                // Query ordering makes the first Contact the deterministic winner.
                if (emailsToMatch.contains(email)
                    && !contactIdsByEmail.containsKey(email)) {
                    contactIdsByEmail.put(email, candidate.Id);
                }
            }
        }

        for (String email : orderedEmails) {
            Result result = new Result();
            result.contactId = email == null ? null : contactIdsByEmail.get(email);
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
