public with sharing class ContactPhoneCleanup {
    /**
     * Removes every character except ASCII digits and '+' from populated phones.
     * Returns each failed contact's Id and its first save error.
     *
     * Security adjustment: the query and update run in user mode to enforce
     * sharing, CRUD, and field-level permissions. The user-mode update overload
     * retains allOrNone=false and still performs just one DML operation.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        List<Contact> contacts = new List<Contact>();

        for (Contact record : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ]) {
            if (record.Phone != null) {
                // Preserve '+' wherever present, as specified by the cleanup rule.
                record.Phone = record.Phone.replaceAll('[^0-9+]', '');
                contacts.add(record);
            }
        }

        if (contacts.isEmpty()) {
            return errorsByContactId;
        }

        Database.SaveResult[] results = Database.update(
            contacts,
            false,
            AccessLevel.USER_MODE
        );

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                // Failed SaveResults may not contain an Id; use the input record.
                errorsByContactId.put(
                    contacts[i].Id,
                    results[i].getErrors()[0].getMessage()
                );
            }
        }

        return errorsByContactId;
    }
}
