public with sharing class PipelineSummary {
    /**
     * Returns Amount totals for the four managed stages, including both dates.
     * Rejects null dates and reversed ranges.
     *
     * One grouped query replaces four queries inside a loop. Although four queries
     * per call is bounded, those queries accumulate across calls in a transaction.
     * Grouping provides the same results while conserving SOQL limits.
     *
     * User mode enforces object and field permissions as well as record access.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null || fromDate > toDate) {
            throw new IllegalArgumentException(
                'Both dates are required, and fromDate must not be after toDate.'
            );
        }

        Map<String, Decimal> totals = new Map<String, Decimal>{
            'Prospecting' => 0,
            'Qualification' => 0,
            'Proposal/Price Quote' => 0,
            'Negotiation/Review' => 0
        };
        Set<String> stages = totals.keySet();

        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :stages
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            Decimal total = (Decimal) result.get('totalAmount');
            totals.put(
                (String) result.get('StageName'),
                total == null ? 0 : total
            );
        }

        return totals;
    }
}
