```apex
/**
 * Closes stale opportunities accessible to the running user.
 *
 * Run the scheduled job as a dedicated automation user with access to every
 * opportunity it must process and permission to update Opportunity.StageName.
 * Sharing and CRUD/FLS are enforced rather than bypassed.
 *
 * Design note:
 * The requested chunking bounds application memory, but does NOT reset governor
 * limits. All chunks share one synchronous transaction: at most 10,000 DML rows,
 * 150 DML statements, and 50,000 queried rows, less anything already consumed.
 * Triggers and flows consume the same transaction's limits.
 *
 * A few thousand records can fit, depending on downstream automation. For larger
 * or unpredictable volumes, use Batch Apex so each execute scope gets separate
 * limits. That would require changing the reporting contract: the scheduler
 * would receive a job ID, and the final count would be reported asynchronously.
 */
public with sharing class StaleOpportunityCloser {
    /**
     * Closes open opportunities whose CloseDate is strictly before cutoff.
     *
     * Returns the number successfully updated. Any failure is propagated rather
     * than returning a misleading partial count. The caller must still commit
     * its transaction for these changes to persist.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            throw new IllegalArgumentException('cutoff must not be null.');
        }

        Integer closedCount = 0;

        // Each update is all-or-none for its chunk. This savepoint also makes
        // the operation atomic across chunks if the caller catches a failure.
        Savepoint operationStart = Database.setSavepoint();

        try {
            for (List<Opportunity> chunk : [
                SELECT Id, StageName
                FROM Opportunity
                WHERE IsClosed = false
                    AND CloseDate < :cutoff
                WITH USER_MODE
            ]) {
                // List-form SOQL loops supply up to 200 records per chunk.
                for (Opportunity opportunity : chunk) {
                    opportunity.StageName = 'Closed Lost';
                }

                Database.update(chunk, true, AccessLevel.USER_MODE);
                closedCount += chunk.size();
            }

            return closedCount;
        } catch (Exception failure) {
            Database.rollback(operationStart);
            throw failure;
        } finally {
            Database.releaseSavepoint(operationStart);
        }
    }
}
