public with sharing class ErpCustomerSync
        implements Queueable, Database.AllowsCallouts {

    private List<CustomerPayload> customers;

    public ErpCustomerSync(List<Account> newAccounts) {
        customers = new List<CustomerPayload>();

        // Capture insertion-time values without an additional database query.
        // An Account trigger invocation contains at most 200 records.
        for (Account accountRecord : newAccounts) {
            customers.add(new CustomerPayload(accountRecord));
        }
    }

    public void execute(QueueableContext context) {
        if (customers.isEmpty()) {
            return;
        }

        HttpRequest request = new HttpRequest();
        request.setEndpoint('callout:ERP/api/customers');
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(JSON.serialize(customers, false));
        request.setTimeout(120000);

        // The expected response is 202 Accepted.
        // Error handling and retries are outside this ticket's scope.
        new Http().send(request);
    }

    private class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Account accountRecord) {
            // Converting an Apex Id to String produces its 18-character form.
            salesforceId = String.valueOf(accountRecord.Id);
            name = accountRecord.Name;
            country = String.isBlank(accountRecord.BillingCountry)
                ? null
                : accountRecord.BillingCountry;
        }
    }
}
