```apex
trigger OpportunityTrigger on Opportunity (
    after insert,
    after update,
    after delete,
    after undelete
) {
    /*
     * Deliberate differences:
     * - Collect account IDs and dispatch once per trigger invocation, not once
     *   per opportunity. A batch of 200 would exceed the 50-future-call limit
     *   if each opportunity scheduled its own future.
     * - Also handle account reassignment, deletion, and undeletion so those
     *   operations cannot leave account ratings stale.
     */
    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isDelete) {
        for (Opportunity opportunity : Trigger.old) {
            accountIds.add(opportunity.AccountId);
        }
    } else {
        for (Opportunity opportunity : Trigger.new) {
            if (Trigger.isUpdate) {
                Opportunity previous = Trigger.oldMap.get(opportunity.Id);

                if (opportunity.StageName == previous.StageName
                    && opportunity.Amount == previous.Amount
                    && opportunity.AccountId == previous.AccountId) {
                    continue;
                }

                // Recalculate both sides of an account reassignment.
                accountIds.add(previous.AccountId);
            }

            accountIds.add(opportunity.AccountId);
        }
    }

    accountIds.remove(null);

    if (!accountIds.isEmpty()) {
        AccountRatingService.enqueueRecalculation(accountIds);
    }
}
