File: force-app/main/default/classes/AccountRatingService.cls
```apex
/*
 * This service intentionally runs without sharing and uses system-mode DML:
 * Rating is a derived account-wide value, not a calculation limited to the
 * initiating user's visible opportunities or field-edit permissions.
 * It is invoked by automation and is not exposed as a user-facing endpoint.
 */
public without sharing class AccountRatingService {
    private static final Decimal HOT_THRESHOLD = 100000;

    /*
     * Normally dispatches one bulk future call.
     *
     * Future methods cannot be called from future or Batch Apex contexts.
     * Use one bulk Queueable in asynchronous contexts instead, also supporting
     * integrations that perform opportunity DML from Queueable Apex.
     */
    public static void enqueueRecalculation(Set<Id> accountIds) {
        Set<Id> requestedIds = cleanAccountIds(accountIds);
        if (requestedIds.isEmpty()) {
            return;
        }

        if (System.isFuture() || System.isBatch() || System.isQueueable()
            || Limits.getFutureCalls() >= Limits.getLimitFutureCalls()) {
            System.enqueueJob(new RecalculationJob(requestedIds));
        } else {
            recalculate(requestedIds);
        }
    }

    @future
    public static void recalculate(Set<Id> accountIds) {
        recalculateNow(accountIds);
    }

    private static void recalculateNow(Set<Id> accountIds) {
        Set<Id> requestedIds = cleanAccountIds(accountIds);
        if (requestedIds.isEmpty()) {
            return;
        }

        /*
         * Serialize competing recalculations before reading the pipeline.
         * Query current data rather than trusting values captured when the
         * asynchronous work was scheduled.
         */
        List<Account> accounts = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :requestedIds
            FOR UPDATE
        ];

        if (accounts.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = new Map<Id, Account>(accounts).keySet();
        Map<Id, String> ratingByAccountId = new Map<Id, String>();

        /*
         * A group exists whenever an account has an open opportunity, even
         * when all its Amount values are null. Such an account is Warm.
         * IsClosed supports custom opportunity stages correctly.
         */
        for (AggregateResult result : [
            SELECT AccountId, MAX(Amount) largestAmount
            FROM Opportunity
            WHERE AccountId IN :existingAccountIds
                AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('AccountId');
            Decimal largestAmount = (Decimal) result.get('largestAmount');

            ratingByAccountId.put(
                accountId,
                largestAmount != null && largestAmount >= HOT_THRESHOLD
                    ? 'Hot'
                    : 'Warm'
            );
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account account : accounts) {
            String desiredRating = ratingByAccountId.containsKey(account.Id)
                ? ratingByAccountId.get(account.Id)
                : 'Cold';

            if (account.Rating != desiredRating) {
                accountsToUpdate.add(new Account(
                    Id = account.Id,
                    Rating = desiredRating
                ));
            }
        }

        // Do not silently swallow failures or leave a partially applied batch.
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private static Set<Id> cleanAccountIds(Set<Id> accountIds) {
        Set<Id> cleanedIds = new Set<Id>();

        if (accountIds != null) {
            cleanedIds.addAll(accountIds);
            cleanedIds.remove(null);
        }

        return cleanedIds;
    }

    private class RecalculationJob implements Queueable {
        private Set<Id> accountIds;

        private RecalculationJob(Set<Id> accountIds) {
            this.accountIds = cleanAccountIds(accountIds);
        }

        public void execute(QueueableContext context) {
            recalculateNow(accountIds);
        }
    }
}
