```apex
/*
 * Trusted, internal workflow automation: deliberately runs in system
 * context so Case ownership/sharing changes do not prevent survey Tasks.
 * The submitted Case IDs originate from the trigger, not an exposed API.
 *
 * Contact and CaseNumber are resolved when the job executes. A Case
 * whose contact has since been removed is skipped.
 *
 * A future vendor integration should use bounded callout batches and
 * durable retry/error tracking rather than one enqueue per trigger row.
 */
public without sharing class CaseSurveyJob implements Queueable {
    private Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = new Set<Id>();
        if (caseIds != null) {
            this.caseIds.addAll(caseIds);
        }
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Task> surveyTasks = new List<Task>();
        Date dueDate = Date.today().addDays(2);

        for (Case c : [
            SELECT Id, ContactId, CaseNumber
            FROM Case
            WHERE Id IN :caseIds
              AND ContactId != null
        ]) {
            surveyTasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status = 'Not Started'
            ));
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        Database.SaveResult[] results = Database.insert(surveyTasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error error : results[i].getErrors()) {
                    // Diagnostics only; debug logs are not durable retry storage.
                    // Do not throw here and roll back successful Task inserts.
                    System.debug(
                        LoggingLevel.ERROR,
                        'CSAT Task creation failed. JobId=' +
                        context.getJobId() +
                        ', CaseId=' + surveyTasks[i].WhatId +
                        ', StatusCode=' + error.getStatusCode() +
                        ', Message=' + error.getMessage()
                    );
                }
            }
        }
    }
}
