     *
     * Instead, one bulk call with allOrNone=false allows valid messages to
     * succeed independently of individual message failures. Transaction-wide
     * failures, such as governor limits, can still prevent sending.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Avoid duplicate reminders when the input contains repeated IDs.
        Set<Id> uniqueIds = new Set<Id>(opportunityIds);
        uniqueIds.remove(null);
        if (uniqueIds.isEmpty()) {
            return 0;
        }

        // Enforce the running user's record access and object/field permissions.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId, CloseDate
            FROM Opportunity
            WHERE Id IN :uniqueIds
            WITH USER_MODE
        ];

        List<Messaging.SingleEmailMessage> messages =
            new List<Messaging.SingleEmailMessage>();

        for (Opportunity opportunity : opportunities) {
            Messaging.SingleEmailMessage message =
                new Messaging.SingleEmailMessage();

            // Address the User by ID rather than by their email address.
            message.setTargetObjectId(opportunity.OwnerId);
            message.setSaveAsActivity(false);
            message.setSubject('Renewal due: ' + opportunity.Name);
            message.setPlainTextBody(
                'The renewal for opportunity "' + opportunity.Name +
                '" is due. Close date: ' +
                String.valueOf(opportunity.CloseDate) +
                '. Please review the opportunity and take the appropriate action.'
            );

            messages.add(message);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Messaging.SendEmailResult[] results =
            Messaging.sendEmail(messages, false);

        Integer successCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
