];

export default class AccountHeader extends LightningElement {
    _recordId;
    record;
    error;
    currencyCode = CURRENCY;

    @api
    get recordId() {
        return this._recordId;
    }

    set recordId(value) {
        if (value !== this._recordId) {
            this._recordId = value;
            // Do not display the previous account while the new one loads.
            this.record = undefined;
            this.error = undefined;
        }
    }

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ data, error }) {
        this.record = data;
        this.error = error;
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get accountName() {
        return this.record
            ? getFieldValue(this.record, NAME_FIELD)
            : undefined;
    }

    get industry() {
        return this.record
            ? getFieldValue(this.record, INDUSTRY_FIELD)
            : undefined;
    }

    get annualRevenue() {
        return this.record
            ? getFieldValue(this.record, REVENUE_FIELD)
            : undefined;
    }

    get ownerName() {
        return this.record
            ? getFieldValue(this.record, OWNER_NAME_FIELD)
            : undefined;
    }

