import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60_000;

export default class QueueMonitor extends LightningElement {
    waiting = 0;
    longestWaitMinutes = 0;
    hasStats = false;
    errorMessage;

    _active = false;
    _inFlight = false;
    _intervalId = null;
    _generation = 0;

    _onVisibilityChange = () => {
        this.restartPolling();
    };

    connectedCallback() {
        if (this._active) {
            return;
        }

        this._active = true;
        this._generation += 1;

        document.addEventListener(
            'visibilitychange',
            this._onVisibilityChange
        );

        this.restartPolling();
    }

    disconnectedCallback() {
        this._active = false;
        this._generation += 1;
        this.stopPolling();

        document.removeEventListener(
            'visibilitychange',
            this._onVisibilityChange
        );

        // Apex promises cannot be canceled. Keep the in-flight guard until
        // settlement, including if this instance reconnects before then.
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    restartPolling() {
        this.stopPolling();

        if (!this._active || document.visibilityState === 'hidden') {
            return;
        }

        void this.loadStats();

        this._intervalId = setInterval(() => {
            void this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    async loadStats() {
        if (
            !this._active ||
            document.visibilityState === 'hidden' ||
            this._inFlight
        ) {
            return;
        }

        this._inFlight = true;
        const generation = this._generation;

        try {
            const stats = await getQueueStats();

            // Ignore responses belonging to a previous attachment.
            if (!this._active || generation !== this._generation) {
                return;
            }

            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.hasStats = true;
            this.errorMessage = undefined;
        } catch (error) {
            if (!this._active || generation !== this._generation) {
                return;
            }

            this.errorMessage =
                error?.body?.message ||
                error?.message ||
                'Unable to load queue statistics.';
        } finally {
            this._inFlight = false;
        }
    }
}
