import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' '
]);

export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    _value;
    _activeIndex = -1;

    @api
    get options() {
        return this._options.map((option) => ({ ...option }));
    }

    set options(options) {
        this._options = Array.isArray(options)
            ? options.map((option) => ({
                  value: option.value,
                  label: option.label
              }))
            : [];

        this.resetActiveOption();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        if (value !== this._value) {
            this._value = value;
            this.resetActiveOption();
        }
    }

    get renderedOptions() {
        return this._options.map((option, index) => ({
            ...option,
            id: `option-${index}`,
            index,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeOptionId() {
        return this._activeIndex >= 0 &&
            this._activeIndex < this._options.length
            ? `option-${this._activeIndex}`
            : undefined;
    }

    resetActiveOption() {
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );

        this._activeIndex =
            selectedIndex >= 0
                ? selectedIndex
                : this._options.length > 0
                  ? 0
                  : -1;
    }

    renderedCallback() {
        const listbox = this.refs.listbox;
        const activeOption =
            listbox.querySelectorAll('[role="option"]')[this._activeIndex];

        // Use the actual rendered ID, including any LWC ID scoping.
        if (activeOption) {
            if (
                listbox.getAttribute('aria-activedescendant') !== activeOption.id
            ) {
                listbox.setAttribute('aria-activedescendant', activeOption.id);
            }
        } else {
            listbox.removeAttribute('aria-activedescendant');
        }
    }

    handleKeyDown(event) {
        if (!HANDLED_KEYS.has(event.key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(
                    this._activeIndex + 1,
                    this._options.length - 1
                );
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(this._activeIndex - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);

        // Options never receive DOM focus.
        this.refs.listbox.focus();
        this.selectOption(index);
    }

    selectOption(index) {
        if (
            !Number.isInteger(index) ||
            index < 0 ||
            index >= this._options.length
        ) {
            return;
        }

        this._activeIndex = index;
        const selectedValue = this._options[index].value;

        if (selectedValue === this._value) {
            return;
        }

        this._value = selectedValue;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: selectedValue }
            })
        );
    }
}
