public with sharing class EmployerService {
    /**
     * Sets employers through NPSP's standard primary-affiliation mechanism.
     * Values must be existing Organization Account IDs.
     *
     * Uses one SOQL query and, when changes are needed, one DML statement.
     * NPSP automation performs the corresponding affiliation maintenance.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId == null ||
                contactId.getSObjectType() != Contact.SObjectType ||
                employerId == null ||
                employerId.getSObjectType() != Account.SObjectType) {
                throw new IllegalArgumentException(
                    'Each entry must map a Contact ID to an Organization Account ID.'
                );
            }
        }

        Set<Id> contactIds = employerByContactId.keySet();
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ];

        // Do not silently succeed when some requested contacts are inaccessible
        // or do not exist. No records have been changed at this point.
        if (contacts.size() != contactIds.size()) {
            throw new IllegalArgumentException(
                'One or more requested contacts do not exist or are not accessible.'
            );
        }

        List<Contact> changes = new List<Contact>();
        for (Contact existingContact : contacts) {
            Id employerId = employerByContactId.get(existingContact.Id);
            if (existingContact.npsp__Primary_Affiliation__c != employerId) {
                changes.add(new Contact(
                    Id = existingContact.Id,
                    npsp__Primary_Affiliation__c = employerId
                ));
            }
        }

        if (!changes.isEmpty()) {
            // NPSP maintains the Current primary affiliation and retires the
            // previous primary affiliation as Former with today's end date.
            // Never change AccountId: the contact remains in its household.
            // User-mode DML enforces access; this statement is all-or-none.
            update as user changes;
        }
    }
}
