public with sharing class RecurringGiftService {
    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final Set<String> PAYMENT_METHODS = new Set<String>{
        'Credit Card', 'ACH', 'Check'
    };

    // Enhanced Recurring Donations' native Day of Month picklist API value.
    private static final String LAST_DAY_OF_MONTH = 'Last_Day';

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> donationIds = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return donationIds;
        }

        // Validate the entire batch before any DML.
        for (Integer i = 0; i < requests.size(); i++) {
            validateRequest(requests[i], i);
        }

        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            Boolean isFixed =
                request.installments != null && request.installments > 0;

            npe03__Recurring_Donation__c donation =
                new npe03__Recurring_Donation__c();

            // Provide a name without querying Contacts. NPSP naming automation
            // may replace it according to the org's configured naming rules.
            donation.Name =
                'Monthly Gift - ' + String.valueOf(request.contactId) +
                ' - ' + String.valueOf(request.startDate);

            donation.npe03__Contact__c = request.contactId;
            donation.npe03__Amount__c = request.amount;
            donation.npe03__Date_Established__c = request.startDate;
            donation.npe03__Installment_Period__c = 'Monthly';

            donation.npsp__InstallmentFrequency__c = 1;
            donation.npsp__StartDate__c = request.startDate;
            donation.npsp__Day_of_Month__c =
                request.dayOfMonth == 31
                    ? LAST_DAY_OF_MONTH
                    : String.valueOf(request.dayOfMonth);

            donation.npsp__RecurringType__c = isFixed ? 'Fixed' : 'Open';
            if (isFixed) {
                donation.npe03__Installments__c = request.installments;
            }

            donation.npsp__Status__c = 'Active';
            donation.npsp__PaymentMethod__c = request.paymentMethod;

            // Use Enhanced scheduling fields rather than legacy schedule/status
            // fields. NPSP derives payment/end dates and creates Opportunities.
            donations.add(donation);
        }

        // One all-or-none DML statement. User mode enforces CRUD, FLS, and
        // record access, including access to the referenced donor Contacts.
        insert as user donations;

        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }

        return donationIds;
    }

    private static void validateRequest(GiftRequest request, Integer index) {
        String prefix = 'Request ' + String.valueOf(index + 1) + ': ';

        if (request == null) {
            throw new RecurringGiftException(prefix + 'request is required.');
        }
        if (request.contactId == null) {
            throw new RecurringGiftException(prefix + 'contactId is required.');
        }
        if (request.contactId.getSObjectType() != Contact.SObjectType) {
            throw new RecurringGiftException(
                prefix + 'contactId must identify a Contact.'
            );
        }
        if (request.amount == null || request.amount <= 0) {
            throw new RecurringGiftException(
                prefix + 'amount must be greater than zero.'
            );
        }
        if (request.dayOfMonth == null ||
            request.dayOfMonth < 1 ||
            request.dayOfMonth > 31) {
            throw new RecurringGiftException(
                prefix + 'dayOfMonth must be between 1 and 31.'
            );
        }
        if (request.startDate == null) {
            throw new RecurringGiftException(prefix + 'startDate is required.');
        }
        if (request.installments != null && request.installments < 0) {
            throw new RecurringGiftException(
                prefix + 'installments must be null, zero, or positive.'
            );
        }
        if (!PAYMENT_METHODS.contains(request.paymentMethod)) {
            throw new RecurringGiftException(
                prefix + 'paymentMethod must be Credit Card, ACH, or Check.'
            );
        }
    }
