public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    /**
     * Replaces an opportunity's allocations with percentage-based allocations.
     * NPSP owns the calculated amounts and recalculates them when the
     * opportunity amount changes.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        if (opportunityId == null ||
            opportunityId.getSObjectType() != Opportunity.SObjectType) {
            throw new AllocationException('A valid Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal totalPercent = 0;
        Set<Id> gauIds = new Set<Id>();
        List<npsp__Allocation__c> replacements =
            new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null ||
                gauId.getSObjectType() !=
                    npsp__General_Accounting_Unit__c.SObjectType) {
                throw new AllocationException(
                    'Every allocation must reference a valid GAU Id.'
                );
            }

            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'Every percentage must be greater than zero.'
                );
            }

            totalPercent += percent;
            gauIds.add(gauId);

            // Supply Percent, not Amount. Do not populate Payment, Campaign,
            // or Recurring Donation: these are opportunity allocations.
            replacements.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent
            ));
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'The total percentage cannot exceed 100.'
            );
        }

        Savepoint replacementSavepoint = null;

        try {
            // Check write permissions before deleting any existing allocations.
            if (!npsp__Allocation__c.SObjectType.getDescribe().isCreateable() ||
                !npsp__Allocation__c.npsp__Opportunity__c
                    .getDescribe().isCreateable() ||
                !npsp__Allocation__c.npsp__General_Accounting_Unit__c
                    .getDescribe().isCreateable() ||
                !npsp__Allocation__c.npsp__Percent__c
                    .getDescribe().isCreateable()) {
                throw new AllocationException(
                    'You do not have permission to create these allocations.'
                );
            }

            // Serialize concurrent calls for the same opportunity.
            List<Opportunity> opportunities = [
                SELECT Id
                FROM Opportunity
                WHERE Id = :opportunityId
                WITH USER_MODE
                FOR UPDATE
            ];

            if (opportunities.isEmpty()) {
                throw new AllocationException(
                    'The opportunity does not exist or is not accessible.'
                );
            }

            List<npsp__General_Accounting_Unit__c> gaus = [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
                WITH USER_MODE
            ];

            if (gaus.size() != gauIds.size()) {
                throw new AllocationException(
                    'One or more GAUs do not exist or are not accessible.'
                );
            }

            for (npsp__General_Accounting_Unit__c gau : gaus) {
                if (gau.npsp__Active__c != true) {
                    throw new AllocationException(
                        'Inactive GAUs cannot receive allocations: ' + gau.Id
                    );
                }
            }

            List<npsp__Allocation__c> existing = [
                SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId
                WITH USER_MODE
            ];

            if (!existing.isEmpty() &&
                !npsp__Allocation__c.SObjectType.getDescribe().isDeletable()) {
                throw new AllocationException(
                    'You do not have permission to delete existing allocations.'
                );
            }

            // Explicit rollback preserves the original allocations even if
            // a caller catches an insertion or automation failure.
            replacementSavepoint = Database.setSavepoint();

            if (!existing.isEmpty()) {
                delete as user existing;
            }
            insert as user replacements;

            return replacements;
        } catch (AllocationException e) {
            if (replacementSavepoint != null) {
                Database.rollback(replacementSavepoint);
            }
            throw e;
        } catch (Exception e) {
            if (replacementSavepoint != null) {
                Database.rollback(replacementSavepoint);
            }
            throw new AllocationException(
                'Unable to replace GAU allocations: ' + e.getMessage(),
                e
            );
        }
    }
}
