public with sharing class HouseholdService {
    public class HouseholdCreationException extends Exception {}

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('At least one household member is required.');
        }

        // Work on copies so a failed call does not leave rolled-back IDs or
        // AccountIds on the caller's Contact instances.
        List<Contact> pendingMembers = new List<Contact>();
        for (Contact member : members) {
            if (member == null || member.Id != null || member.AccountId != null) {
                throw new IllegalArgumentException(
                    'Every member must be a new Contact without an AccountId.'
                );
            }
            pendingMembers.add(member.clone(false, false, false, false));
        }

        Schema.RecordTypeInfo householdRecordType =
            Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
                .get('HH_Account');

        if (householdRecordType == null ||
            !householdRecordType.isActive() ||
            !householdRecordType.isAvailable()) {
            throw new HouseholdCreationException(
                'The HH_Account record type must be active and available to the running user.'
            );
        }

        Savepoint savepoint = Database.setSavepoint();
        try {
            // Let NPSP create and name exactly one household. Inserting every
            // unparented Contact together would create separate households.
            Contact firstMember = pendingMembers[0];
            insert as user firstMember;

            // NPSP can assign AccountId during trigger processing; requery it
            // rather than relying on the in-memory Contact.
            Contact persistedFirstMember = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :firstMember.Id
                WITH USER_MODE
            ];

            Id householdId = persistedFirstMember.AccountId;
            if (householdId == null) {
                throw new HouseholdCreationException(
                    'NPSP did not create a household for the first member.'
                );
            }

            // Ensure the required record type and primary contact without
            // supplying a Name or overriding NPSP-generated greetings.
            Account household = new Account(
                Id = householdId,
                RecordTypeId = householdRecordType.getRecordTypeId(),
                npe01__One2OneContact__c = firstMember.Id
            );
            update as user household;

            // Explicit parenting prevents NPSP from creating additional
            // households. Its Contact triggers maintain naming and greetings.
            List<Contact> remainingMembers = new List<Contact>();
            for (Integer i = 1; i < pendingMembers.size(); i++) {
                Contact member = pendingMembers[i];
                member.AccountId = householdId;
                remainingMembers.add(member);
            }

            if (!remainingMembers.isEmpty()) {
                insert as user remainingMembers;
            }

            return householdId;
        } catch (Exception ex) {
            // Include NPSP's trigger-created records in the rollback, even if
            // the caller catches the exception and continues its transaction.
            Database.rollback(savepoint);
            throw ex;
        }
    }
}
