public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(
        List<SoftCreditRequest> requests
    ) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Map<String, SoftCreditRequest> requestsByPair =
            new Map<String, SoftCreditRequest>();

        // Complete request validation before performing any DML.
        for (SoftCreditRequest request : requests) {
            if (request == null ||
                request.opportunityId == null ||
                request.contactId == null) {
                throw new SoftCreditException(
                    'Each request must specify an opportunity and a contact.'
                );
            }

            if (request.opportunityId.getSObjectType() !=
                    Opportunity.SObjectType ||
                request.contactId.getSObjectType() != Contact.SObjectType) {
                throw new SoftCreditException(
                    'The opportunity or contact Id has the wrong object type.'
                );
            }

            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException(
                    'Each partial soft credit amount must be positive.'
                );
            }

            String key = pairKey(
                request.opportunityId,
                request.contactId
            );
            if (requestsByPair.containsKey(key)) {
                throw new SoftCreditException(
                    'An opportunity/contact pair occurs more than once.'
                );
            }

            requestsByPair.put(key, request);
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        // Query 1. User mode enforces sharing, CRUD, and field permissions.
        Map<Id, Opportunity> opportunitiesById =
            new Map<Id, Opportunity>([
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :opportunityIds
                WITH USER_MODE
            ]);

        for (SoftCreditRequest request : requests) {
            Opportunity opportunity =
                opportunitiesById.get(request.opportunityId);

            if (opportunity == null) {
                throw new SoftCreditException(
                    'An opportunity does not exist or is not accessible.'
                );
            }

            if (request.contactId ==
                opportunity.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'The opportunity primary contact cannot receive a ' +
                    'partial soft credit on that opportunity.'
                );
            }

            if (opportunity.Amount == null ||
                request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'A partial soft credit amount cannot exceed the ' +
                    'opportunity amount, which must be populated.'
                );
            }
        }

        // Query 2. Contact_Name__c is the writable Contact lookup.
        // Contact__c is the NPSP display/formula field, not that lookup.
        Map<String, npsp__Partial_Soft_Credit__c> originalCreditByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c credit : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact_Name__c IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String key = pairKey(
                credit.npsp__Opportunity__c,
                credit.npsp__Contact_Name__c
            );
            if (requestsByPair.containsKey(key) &&
                !originalCreditByPair.containsKey(key)) {
                originalCreditByPair.put(key, credit);
            }
        }

        // Query 3. Do not restrict Role: an existing Household Member
        // role must be reused rather than overlooked.
        Map<String, List<OpportunityContactRole>> rolesByPair =
            new Map<String, List<OpportunityContactRole>>();

        for (OpportunityContactRole contactRole : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
            WITH USER_MODE
            ORDER BY IsPrimary DESC, CreatedDate ASC, Id ASC
        ]) {
            String key = pairKey(
                contactRole.OpportunityId,
                contactRole.ContactId
            );
            if (!requestsByPair.containsKey(key)) {
                continue;
            }
            if (!rolesByPair.containsKey(key)) {
                rolesByPair.put(key, new List<OpportunityContactRole>());
            }
            rolesByPair.get(key).add(contactRole);
        }

        List<OpportunityContactRole> rolesToDelete =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToSave =
            new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> retainedRoleByPair =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(
                request.opportunityId,
                request.contactId
            );
            List<OpportunityContactRole> existingRoles =
                rolesByPair.get(key);

            OpportunityContactRole retained;
            Boolean wasPrimary = false;

            if (existingRoles != null) {
                retained = existingRoles[0];
                npsp__Partial_Soft_Credit__c originalCredit =
                    originalCreditByPair.get(key);

                for (OpportunityContactRole candidate : existingRoles) {
                    wasPrimary = wasPrimary || candidate.IsPrimary;
                    // Preserve the OCR already referenced by the retained
                    // partial credit whenever that reference is valid.
                    if (originalCredit != null &&
                        referencesRole(
                            originalCredit.npsp__Contact_Role_ID__c,
                            candidate.Id
                        )) {
                        retained = candidate;
                    }
                }

                for (OpportunityContactRole candidate : existingRoles) {
                    if (candidate.Id != retained.Id) {
                        rolesToDelete.add(
                            new OpportunityContactRole(Id = candidate.Id)
                        );
                    }
                }
            }

            // Use sparse update records; do not rewrite parent fields.
            OpportunityContactRole toSave;
            if (retained == null) {
                toSave = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role,
                    IsPrimary = false
                );
            } else {
                toSave = new OpportunityContactRole(
                    Id = retained.Id,
                    Role = request.role,
                    IsPrimary = wasPrimary
                );
            }

            rolesToSave.add(toSave);
            retainedRoleByPair.put(key, toSave);
        }

        // DML statements 1 and 2. Required validation is already complete.
        // Delete duplicate OCRs before restoring the retained OCR's role.
        if (!rolesToDelete.isEmpty()) {
            delete as user rolesToDelete;
        }
        upsert as user rolesToSave;

        // Query 4. Re-read after OCR DML so NPSP-created or removed partial
        // credits are reflected in the upsert plan.
        Map<String, List<npsp__Partial_Soft_Credit__c>> creditsByPair =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();

        for (npsp__Partial_Soft_Credit__c credit : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact_Name__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact_Name__c IN :contactIds
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ]) {
            String key = pairKey(
                credit.npsp__Opportunity__c,
                credit.npsp__Contact_Name__c
            );
            if (!requestsByPair.containsKey(key)) {
                continue;
            }
            if (!creditsByPair.containsKey(key)) {
                creditsByPair.put(
                    key,
                    new List<npsp__Partial_Soft_Credit__c>()
                );
            }
            creditsByPair.get(key).add(credit);
        }

        List<npsp__Partial_Soft_Credit__c> creditsToDelete =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> creditsToSave =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(
                request.opportunityId,
                request.contactId
            );
            List<npsp__Partial_Soft_Credit__c> existingCredits =
                creditsByPair.get(key);
            npsp__Partial_Soft_Credit__c retainedCredit;

            if (existingCredits != null) {
                retainedCredit = existingCredits[0];
                npsp__Partial_Soft_Credit__c originalCredit =
                    originalCreditByPair.get(key);

                // Prefer updating the original record if it still exists.
                for (npsp__Partial_Soft_Credit__c candidate :
                     existingCredits) {
                    if (originalCredit != null &&
                        candidate.Id == originalCredit.Id) {
                        retainedCredit = candidate;
                    }
                }

                // Also repair pre-existing duplicate partial credits.
                for (npsp__Partial_Soft_Credit__c candidate :
                     existingCredits) {
                    if (candidate.Id != retainedCredit.Id) {
                        creditsToDelete.add(
                            new npsp__Partial_Soft_Credit__c(
                                Id = candidate.Id
                            )
                        );
                    }
                }
            }

            npsp__Partial_Soft_Credit__c toSave =
                new npsp__Partial_Soft_Credit__c();

            if (retainedCredit == null) {
                toSave.npsp__Opportunity__c = request.opportunityId;
                toSave.npsp__Contact_Name__c = request.contactId;
            } else {
                toSave.Id = retainedCredit.Id;
            }

            toSave.npsp__Amount__c = request.amount;
            toSave.npsp__Role_Name__c = request.role;
            toSave.npsp__Contact_Role_ID__c =
                String.valueOf(retainedRoleByPair.get(key).Id);
            creditsToSave.add(toSave);
        }

        // DML statements 3 and 4. DML errors propagate to the caller.
        if (!creditsToDelete.isEmpty()) {
            delete as user creditsToDelete;
        }
        upsert as user creditsToSave;
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' +
            String.valueOf(contactId);
    }

    private static Boolean referencesRole(String reference, Id roleId) {
        if (String.isBlank(reference)) {
            return false;
        }

        // The NPSP link is text and can contain a 15- or 18-character Id.
        String fullId = String.valueOf(roleId);
        return fullId.equals(reference) ||
            fullId.substring(0, 15).equals(reference);
    }
}
