public with sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'The number of payments must be at least 1.'
            );
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity is required.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        // Serialize requests for the same opportunity before reading payments.
        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            FOR UPDATE
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException(
                'The opportunity was not found or is not accessible.'
            );
        }

        Opportunity pledge = opportunities[0];
        if (pledge.IsClosed) {
            throw new PaymentPlanException(
                'A payment plan cannot be scheduled for a closed opportunity.'
            );
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c,
                   npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            FOR UPDATE
        ];

        Decimal historicalAmount = 0;
        List<npe01__OppPayment__c> paymentsToDelete =
            new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            if (payment.npe01__Paid__c == true ||
                payment.npe01__Written_Off__c == true) {
                // Count a payment only once, even if both flags are true.
                if (payment.npe01__Payment_Amount__c != null) {
                    historicalAmount += payment.npe01__Payment_Amount__c;
                }
            } else {
                paymentsToDelete.add(payment);
            }
        }

        Decimal pledgeAmount = pledge.Amount == null ? 0 : pledge.Amount;
        Decimal outstandingAmount = pledgeAmount - historicalAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'The outstanding amount must be greater than zero.'
            );
        }

        // Fail before modifying anything if the direct DML cannot fit.
        Integer availableDmlRows =
            Limits.getLimitDmlRows() - Limits.getDmlRows();
        if (numberOfPayments > availableDmlRows - paymentsToDelete.size()) {
            throw new PaymentPlanException(
                'The payment plan exceeds the remaining transaction DML row limit.'
            );
        }

        Decimal installmentAmount =
            (outstandingAmount / numberOfPayments)
                .setScale(2, RoundingMode.DOWN);

        List<npe01__OppPayment__c> installments =
            new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount = installmentAmount;
            if (i == numberOfPayments - 1) {
                amount = outstandingAmount -
                    (installmentAmount * (numberOfPayments - 1));
            }

            installments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Payment_Date__c = null,
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // Explicit rollback keeps replacement atomic even if the caller catches
        // the exception. User-mode DML enforces access and field permissions.
        Savepoint replacementSavepoint = Database.setSavepoint();
        try {
            if (!paymentsToDelete.isEmpty()) {
                delete as user paymentsToDelete;
            }
            insert as user installments;
        } catch (Exception ex) {
            Database.rollback(replacementSavepoint);
            throw new PaymentPlanException(
                'The payment plan could not be saved: ' + ex.getMessage()
            );
        }

        // Insertion populates IDs without changing the list's schedule order.
        return installments;
    }
}
