public with sharing class GiftService {
    public class GiftServiceException extends Exception {}

    /**
     * Records an already-received donation.
     *
     * The caller must have access to the household's contacts and permission
     * to create/update/delete the donation's contact roles and payments.
     * NPSP-created records are reconciled rather than blindly inserted.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
        if (contactId == null || contactId.getSObjectType() != Contact.SObjectType) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist or is inaccessible.');
        }

        Contact donor = donors[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact must belong to a household account.');
        }

        // Discover the complete membership, then require access to every member.
        // A sharing-filtered query alone could silently omit household members.
        Set<Id> householdContactIds =
            new RecordInventory().householdContactIds(donor.AccountId);

        List<Contact> accessibleMembers = [
            SELECT Id
            FROM Contact
            WHERE Id IN :householdContactIds
            WITH USER_MODE
        ];
        requireCompleteAccess(householdContactIds.size(), accessibleMembers.size());

        String donorName = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;

        Opportunity gift = new Opportunity(
            Name = donorName + ' Donation ' + String.valueOf(giftDate),
            AccountId = donor.AccountId,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            Amount = amount,
            npsp__Primary_Contact__c = contactId
        );

        Savepoint checkpoint = Database.setSavepoint();
        try {
            // NPSP may create contact roles and payments during this insert.
            insert as user gift;

            reconcileRoles(gift.Id, contactId, householdContactIds);
            reconcilePayment(gift.Id, amount, giftDate);

            // Do not return success if synchronous automation changed the result.
            verifyGift(
                gift.Id,
                donor.AccountId,
                contactId,
                householdContactIds,
                amount,
                giftDate,
                gift.Name
            );

            return gift.Id;
        } catch (Exception ex) {
            // Also protect callers that catch the exception and continue.
            Database.rollback(checkpoint);
            throw ex;
        }
    }

    private static void reconcileRoles(
        Id opportunityId,
        Id donorId,
        Set<Id> householdContactIds
    ) {
        List<OpportunityContactRole> existingRoles = loadRoles(opportunityId);
        Map<Id, OpportunityContactRole> retainedByContact =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> duplicates =
            new List<OpportunityContactRole>();

        // loadRoles orders primary roles first, so preserve an existing primary
        // role rather than deleting it and potentially clearing NPSP's lookup.
        for (OpportunityContactRole role : existingRoles) {
            if (retainedByContact.containsKey(role.ContactId)) {
                duplicates.add(role);
            } else {
                retainedByContact.put(role.ContactId, role);
            }
        }

        List<OpportunityContactRole> changes =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> additions =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole role : retainedByContact.values()) {
            Boolean shouldBePrimary = role.ContactId == donorId;
            String requiredRole = role.Role;

            if (householdContactIds.contains(role.ContactId)) {
                requiredRole = shouldBePrimary ? 'Donor' : 'Household Member';
            }

            // Preserve unrelated NPSP roles, but never another primary role.
            if (role.IsPrimary != shouldBePrimary || role.Role != requiredRole) {
                role.IsPrimary = shouldBePrimary;
                role.Role = requiredRole;
                changes.add(role);
            }
        }

        for (Id memberId : householdContactIds) {
            if (!retainedByContact.containsKey(memberId)) {
                additions.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = memberId,
                    IsPrimary = memberId == donorId,
                    Role = memberId == donorId ? 'Donor' : 'Household Member'
                ));
            }
        }

        if (!duplicates.isEmpty()) {
            delete as user duplicates;
        }
        if (!changes.isEmpty()) {
            update as user changes;
        }
        if (!additions.isEmpty()) {
            insert as user additions;
        }
    }

    private static void reconcilePayment(
        Id opportunityId,
        Decimal amount,
        Date giftDate
    ) {
        List<npe01__OppPayment__c> payments = loadPayments(opportunityId);

        if (payments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            insert as user payment;
            return;
        }

        // Reuse NPSP's automatically created payment.
        npe01__OppPayment__c retained = payments[0];
        List<npe01__OppPayment__c> duplicates =
            new List<npe01__OppPayment__c>();

        for (Integer i = 1; i < payments.size(); i++) {
            duplicates.add(payments[i]);
        }
        if (!duplicates.isEmpty()) {
            delete as user duplicates;
        }

        if (
            retained.npe01__Payment_Amount__c != amount ||
            retained.npe01__Payment_Date__c != giftDate ||
            retained.npe01__Scheduled_Date__c != giftDate ||
            retained.npe01__Paid__c != true
        ) {
            retained.npe01__Payment_Amount__c = amount;
            retained.npe01__Payment_Date__c = giftDate;
            retained.npe01__Scheduled_Date__c = giftDate;
            retained.npe01__Paid__c = true;
            update as user retained;
        }
    }

    private static void verifyGift(
        Id opportunityId,
        Id accountId,
        Id donorId,
        Set<Id> householdContactIds,
        Decimal amount,
        Date giftDate,
        String expectedName
    ) {
        Opportunity saved = [
            SELECT Id, Name, AccountId, StageName, CloseDate, Amount,
                   npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
        ];

        if (
            saved.Name != expectedName ||
            saved.AccountId != accountId ||
            saved.StageName != 'Closed Won' ||
            saved.CloseDate != giftDate ||
            saved.Amount != amount ||
            saved.npsp__Primary_Contact__c != donorId
        ) {
            throw new GiftServiceException(
                'Automation changed the required donation values.'
            );
        }

        Set<Id> seenContacts = new Set<Id>();
        for (OpportunityContactRole role : loadRoles(opportunityId)) {
            if (!seenContacts.add(role.ContactId)) {
                throw new GiftServiceException(
                    'Automation created duplicate contact roles.'
                );
            }

            Boolean shouldBePrimary = role.ContactId == donorId;
            if (role.IsPrimary != shouldBePrimary) {
                throw new GiftServiceException(
                    'The donation has an incorrect primary contact role.'
                );
            }

            if (householdContactIds.contains(role.ContactId)) {
                String expectedRole =
                    shouldBePrimary ? 'Donor' : 'Household Member';
                if (role.Role != expectedRole) {
                    throw new GiftServiceException(
                        'The donation has an incorrect household contact role.'
                    );
                }
            }
        }

        if (!seenContacts.containsAll(householdContactIds)) {
            throw new GiftServiceException(
                'The donation is missing household contact roles.'
            );
        }

        List<npe01__OppPayment__c> payments = loadPayments(opportunityId);
        if (
            payments.size() != 1 ||
            payments[0].npe01__Payment_Amount__c != amount ||
            payments[0].npe01__Payment_Date__c != giftDate ||
            payments[0].npe01__Paid__c != true
        ) {
            throw new GiftServiceException(
                'The donation must have exactly one fully paid payment.'
            );
        }
    }

    private static List<OpportunityContactRole> loadRoles(Id opportunityId) {
        Set<Id> allIds = new RecordInventory().roleIds(opportunityId);
        List<OpportunityContactRole> roles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            WITH USER_MODE
            ORDER BY IsPrimary DESC, CreatedDate ASC, Id ASC
        ];
        requireCompleteAccess(allIds.size(), roles.size());
        return roles;
    }

    private static List<npe01__OppPayment__c> loadPayments(Id opportunityId) {
        Set<Id> allIds = new RecordInventory().paymentIds(opportunityId);
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ];
        requireCompleteAccess(allIds.size(), payments.size());
        return payments;
    }

    private static void requireCompleteAccess(Integer total, Integer accessible) {
        if (total != accessible) {
            throw new GiftServiceException(
                'Insufficient access to all records required to record this gift.'
            );
        }
    }

    /**
     * ID-only, privately scoped inventory queries detect records hidden by
     * sharing. They never expose hidden data or perform privileged DML.
     * All business-field reads and all writes execute in user mode.
     */
    private without sharing class RecordInventory {
        public Set<Id> householdContactIds(Id accountId) {
            return new Map<Id, Contact>([
                SELECT Id
                FROM Contact
                WHERE AccountId = :accountId
            ]).keySet();
        }

        public Set<Id> roleIds(Id opportunityId) {
            return new Map<Id, OpportunityContactRole>([
                SELECT Id
                FROM OpportunityContactRole
                WHERE OpportunityId = :opportunityId
            ]).keySet();
        }

        public Set<Id> paymentIds(Id opportunityId) {
            return new Map<Id, npe01__OppPayment__c>([
                SELECT Id
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
            ]).keySet();
        }
    }
}
