public with sharing class FamilyService {
    /**
     * Creates child-to-parent relationships. NPSP creates and links the
     * reciprocal records, selecting Son, Daughter, or Child from its settings.
     *
     * Incomplete pairs, non-Contact IDs, and self-relationships are rejected
     * before any database work. Repeated unordered pairs are processed once.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        Map<String, npe4__Relationship__c> candidatesByPair =
            new Map<String, npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null) {
                throw new IllegalArgumentException(
                    'Both child and parent Contact IDs are required.'
                );
            }
            if (childId.getSObjectType() != Contact.SObjectType ||
                parentId.getSObjectType() != Contact.SObjectType) {
                throw new IllegalArgumentException(
                    'Child and parent IDs must identify Contacts.'
                );
            }
            if (childId == parentId) {
                throw new IllegalArgumentException(
                    'A Contact cannot be its own parent.'
                );
            }

            contactIds.add(childId);
            contactIds.add(parentId);

            String key = pairKey(childId, parentId);
            if (!candidatesByPair.containsKey(key)) {
                candidatesByPair.put(
                    key,
                    new npe4__Relationship__c(
                        npe4__Contact__c = childId,
                        npe4__RelatedContact__c = parentId,
                        npe4__Type__c = 'Parent',
                        npe4__Status__c = 'Current'
                    )
                );
            }
        }

        for (String existingKey : ExistingRelationships.findPairKeys(contactIds)) {
            candidatesByPair.remove(existingKey);
        }

        if (candidatesByPair.isEmpty()) {
            return;
        }

        // Insert only one direction. Inserting reciprocal records ourselves
        // would conflict with NPSP's reciprocal-relationship automation.
        // User-mode DML enforces CRUD, FLS, and record access for the import.
        List<npe4__Relationship__c> toInsert = candidatesByPair.values();
        insert as user toInsert;
    }

    private static String pairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        return first.compareTo(second) <= 0
            ? first + ':' + second
            : second + ':' + first;
    }

    /**
     * Deliberately privileged, read-only duplicate detection: an existing
     * relationship must prevent insertion even when it is hidden by sharing.
     * No relationship data is returned to callers of the public service.
     * All writes remain in user mode.
     */
    private without sharing class ExistingRelationships {
        public Set<String> findPairKeys(Set<Id> contactIds) {
            Set<String> existingKeys = new Set<String>();

            for (npe4__Relationship__c relationship : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM npe4__Relationship__c
                WHERE npe4__Contact__c IN :contactIds
                  AND npe4__RelatedContact__c IN :contactIds
                WITH SYSTEM_MODE
            ]) {
                existingKeys.add(
                    FamilyService.pairKey(
                        relationship.npe4__Contact__c,
                        relationship.npe4__RelatedContact__c
                    )
                );
            }

            return existingKeys;
        }
    }
}
