public with sharing class RecordAccessService {
    private static final Integer ACCESS_QUERY_BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        // Work on a copy so the caller's collection is not modified.
        Set<Id> candidateIds = new Set<Id>(recordIds);
        candidateIds.remove(null);
        List<Id> candidates = new List<Id>(candidateIds);
        Id runningUserId = UserInfo.getUserId();

        // UserRecordAccess accepts at most 200 RecordIds per query.
        // Batch across object types: 2,000 IDs require only 10 queries.
        for (
            Integer startIndex = 0;
            startIndex < candidates.size();
            startIndex += ACCESS_QUERY_BATCH_SIZE
        ) {
            Set<Id> batchIds = new Set<Id>();
            Integer endIndex = Math.min(
                startIndex + ACCESS_QUERY_BATCH_SIZE,
                candidates.size()
            );

            for (Integer i = startIndex; i < endIndex; i++) {
                batchIds.add(candidates[i]);
            }

            for (UserRecordAccess accessRecord : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                    AND RecordId IN :batchIds
            ]) {
                if (accessRecord.HasEditAccess == true) {
                    editableRecordIds.add(accessRecord.RecordId);
                }
            }
        }

        return editableRecordIds;
    }
}
