```apex
public inherited sharing class OpportunityErpSyncFinalizer
    implements TriggerAction.DmlFinalizer {

    // Shared across action instances and trigger chunks until TAF finalizes.
    private static Set<Id> pendingOpportunityIds = new Set<Id>();

    public static void collect(Set<Id> opportunityIds) {
        pendingOpportunityIds.addAll(opportunityIds);
    }

    public void execute(FinalizerHandler.Context context) {
        // TAF invokes this for other objects and nonqualifying operations too.
        if (pendingOpportunityIds.isEmpty()) {
            return;
        }

        Set<Id> idsToSync = new Set<Id>(pendingOpportunityIds);

        // Drain this operation's state before enqueueing so a subsequent DML
        // operation in the same transaction starts with an empty collection.
        pendingOpportunityIds.clear();

        // No DML or callouts in the finalizer. Do not suppress enqueue failures.
        System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
    }
}
