@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    static void reductionGreaterThanHalfIsRejected() {
        Opportunity updated = executeSingleUpdate(1000, 499);

        assertRuleError(updated);
    }

    @IsTest
    static void reductionOfExactlyHalfIsAccepted() {
        Opportunity updated = executeSingleUpdate(1000, 500);

        assertNoErrors(updated);
    }

    @IsTest
    static void increaseIsAccepted() {
        Opportunity updated = executeSingleUpdate(1000, 1200);

        assertNoErrors(updated);
    }

    @IsTest
    static void nullPreviousAmountIsAccepted() {
        // Any exception from beforeUpdate causes this test to fail.
        Opportunity updated = executeSingleUpdate(null, 100);

        assertNoErrors(updated);
    }

    @IsTest
    static void mixedBatchOnlyRejectsRuleViolations() {
        List<Decimal> previousAmounts = new List<Decimal>{
            1000, 1000, 200, 1000, null, 1000, 1000
        };
        List<Decimal> updatedAmounts = new List<Decimal>{
            499, 500, 99, 1200, 10, null, 1000
        };
        List<Boolean> shouldHaveError = new List<Boolean>{
            true, false, true, false, false, false, false
        };

        List<Opportunity> triggerOld = new List<Opportunity>();
        List<Opportunity> triggerNew = new List<Opportunity>();

        for (Integer i = 0; i < previousAmounts.size(); i++) {
            Id opportunityId =
                TriggerTestUtility.getFakeId(Opportunity.SObjectType);

            triggerOld.add(new Opportunity(
                Id = opportunityId,
                Amount = previousAmounts[i]
            ));
            triggerNew.add(new Opportunity(
                Id = opportunityId,
                Amount = updatedAmounts[i]
            ));
        }

        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(triggerNew, triggerOld);

        for (Integer i = 0; i < triggerNew.size(); i++) {
            if (shouldHaveError[i]) {
                assertRuleError(triggerNew[i]);
            } else {
                assertNoErrors(triggerNew[i]);
            }
        }
    }

    private static Opportunity executeSingleUpdate(
        Decimal previousAmount,
        Decimal updatedAmount
    ) {
        Id opportunityId =
            TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        List<Opportunity> triggerOld = new List<Opportunity>{
            new Opportunity(
                Id = opportunityId,
                Amount = previousAmount
            )
        };
        List<Opportunity> triggerNew = new List<Opportunity>{
            new Opportunity(
                Id = opportunityId,
                Amount = updatedAmount
            )
        };

        new TA_Opportunity_GuardAmountDecrease()
            .beforeUpdate(triggerNew, triggerOld);

        return triggerNew[0];
    }

    private static void assertRuleError(Opportunity record) {
        System.Assert.isTrue(
            record.hasErrors(),
            'Expected an error for Opportunity ' + record.Id
        );

        List<Database.Error> errors = record.getErrors();
        System.Assert.areEqual(
            1,
            errors.size(),
            'Expected exactly one error for Opportunity ' + record.Id
        );
        System.Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Unexpected error message for Opportunity ' + record.Id
        );
    }

    private static void assertNoErrors(Opportunity record) {
        System.Assert.isFalse(
            record.hasErrors(),
            'Expected no errors for Opportunity ' + record.Id
        );
        System.Assert.areEqual(
            0,
            record.getErrors().size(),
            'Expected an empty error list for Opportunity ' + record.Id
        );
    }
}
