public without sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validateContacts(triggerNew, new Map<Id, Contact>());
    }

    public void beforeUpdate(
        List<SObject> triggerNew,
        List<SObject> triggerOld
    ) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (SObject record : triggerOld) {
            Contact oldContact = (Contact) record;
            oldById.put(oldContact.Id, oldContact);
        }
        validateContacts(triggerNew, oldById);
    }

    private static void validateContacts(
        List<SObject> triggerNew,
        Map<Id, Contact> oldById
    ) {
        // All working state is invocation-local so partial-save retries
        // evaluate the surviving records again.
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<String> occupiedKeys = new Set<String>();

        for (SObject record : triggerNew) {
            Contact current = (Contact) record;
            Contact previous = oldById.get(current.Id);

            // A record already rejected by another action retains its old
            // database values rather than vacating its old account/email.
            if (current.hasErrors()) {
                String previousKey = keyFor(previous);
                if (previousKey != null) {
                    occupiedKeys.add(previousKey);
                }
                continue;
            }

            Boolean changed = previous == null
                || current.AccountId != previous.AccountId
                || !sameEmailValue(current.Email, previous.Email);

            if (!changed) {
                // Unchanged legacy duplicates are not validated, but their
                // occupied keys still prevent new duplicates.
                String unchangedKey = keyFor(current);
                if (unchangedKey != null) {
                    occupiedKeys.add(unchangedKey);
                }
                continue;
            }

            if (keyFor(current) == null) {
                // Clearing either field vacates the previous key.
                continue;
            }

            candidates.add(current);
            accountIds.add(current.AccountId);
            emails.add(current.Email.toLowerCase());
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Deliberately system-mode/without-sharing: this integrity rule must
        // also detect Contacts the saving user cannot see. Email filtering
        // is case-insensitive; the composite key enforces the exact pair.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
                AND Email IN :emails
        ]) {
            // Batch updates are represented by their proposed values above
            // and below, not by their stale database values.
            if (!oldById.containsKey(existing.Id)) {
                occupiedKeys.add(keyFor(existing));
            }
        }

        Map<String, Contact> firstByKey = new Map<String, Contact>();
        for (Contact candidate : candidates) {
            String candidateKey = keyFor(candidate);
            if (firstByKey.containsKey(candidateKey)) {
                String restoredKey = rejectAndGetOldKey(candidate, oldById);
                if (restoredKey != null) {
                    occupiedKeys.add(restoredKey);
                }
            } else {
                firstByKey.put(candidateKey, candidate);
            }
        }

        // Reject candidates blocked by persisted/unchanged records.
        // A rejected update retains its OLD key, which can in turn block
        // another candidate. Propagate those conflicts without more SOQL.
        // This also allows valid swaps and moves within the same update.
        List<String> blockedQueue = new List<String>();
        blockedQueue.addAll(occupiedKeys);

        for (Integer index = 0; index < blockedQueue.size(); index++) {
            Contact blockedCandidate = firstByKey.remove(blockedQueue[index]);
            if (blockedCandidate == null) {
                continue;
            }

            String restoredKey =
                rejectAndGetOldKey(blockedCandidate, oldById);
            if (restoredKey != null && occupiedKeys.add(restoredKey)) {
                blockedQueue.add(restoredKey);
            }
        }
    }

    private static Boolean sameEmailValue(String first, String second) {
        // String.equals is case-sensitive, unlike Apex's == operator.
        // A case-only edit is still an Email field change.
        return first == null ? second == null : first.equals(second);
    }

    private static String keyFor(Contact record) {
        if (
            record == null
            || record.AccountId == null
            || String.isBlank(record.Email)
        ) {
            return null;
        }
        return String.valueOf(record.AccountId)
            + '|'
            + record.Email.toLowerCase();
    }

    private static String rejectAndGetOldKey(
        Contact record,
        Map<Id, Contact> oldById
    ) {
        record.addError(ERROR_MESSAGE);
        return keyFor(oldById.get(record.Id));
    }
}
