public with sharing class TA_Opportunity_LogAmountChange
    implements TriggerAction.AfterUpdate {

    private static Set<Id> auditedOpportunityIds = new Set<Id>();

    public void afterUpdate(
        List<Opportunity> triggerNew,
        List<Opportunity> triggerOld
    ) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();
        Set<Id> newlyAuditedIds = new Set<Id>();

        for (Opportunity opportunity : triggerNew) {
            Opportunity oldOpportunity = oldById.get(opportunity.Id);

            if (opportunity.Amount != oldOpportunity.Amount
                && !auditedOpportunityIds.contains(opportunity.Id)) {
                // Reserve before DML so nested automation cannot log it again.
                auditedOpportunityIds.add(opportunity.Id);
                newlyAuditedIds.add(opportunity.Id);

                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opportunity.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (tasksToInsert.isEmpty()) {
            return;
        }

        try {
            // Mandatory audit automation intentionally uses system-mode DML.
            // All-or-none insertion prevents silently losing audit records.
            insert tasksToInsert;
        } catch (DmlException failure) {
            auditedOpportunityIds.removeAll(newlyAuditedIds);
            throw failure;
        }
    }
}
